class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp is a dictionary: key = (current_alternating_sum, next_parity), value = max_product
        # next_parity: 0 means next element will be added (even index in subsequence), 1 means subtracted (odd index)
        dp = {}

        for x in nums:
            # Create a copy of current dp states to allow skipping the current number
            new_dp = dp.copy()

            # For each existing subsequence state, try appending x
            for (s, p), prod in dp.items():
                if p == 0:
                    new_s = s + x
                else:
                    new_s = s - x

                new_p = 1 - p
                new_prod = prod * x

                if new_prod <= limit:
                    # Update the new_dp with the new state if it's better
                    key = (new_s, new_p)
                    if key not in new_dp or new_prod > new_dp[key]:
                        new_dp[key] = new_prod

            # Start a new subsequence with just x
            # This corresponds to adding x to an empty subsequence (sum=0, next_parity=0)
            new_s = x  # 0 + x since next_parity for empty is 0 (add)
            new_p = 1  # next element after this would be at odd index (subtract)
            new_prod = x

            if new_prod <= limit:
                key = (new_s, new_p)
                if key not in new_dp or new_prod > new_dp[key]:
                    new_dp[key] = new_prod

            dp = new_dp

        # Check for the target alternating sum k
        # The parity at the end doesn't matter for the sum value, but we need to check both
        ans = -1
        for p in [0, 1]:
            if (k, p) in dp:
                if dp[(k, p)] > ans:
                    ans = dp[(k, p)]

        return ans

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_upto(n, S):
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            num_digits = len(digits)

            # dp(pos, current_sum, current_prod_mod_S, tight, started)
            # We use lru_cache for memoization
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, current_sum, current_prod_mod_S, tight, started):
                # If current sum already exceeds S, no need to proceed
                if current_sum > S:
                    return 0

                # If we've placed all digits
                if pos == num_digits:
                    # Check if we have started (i.e., the number is positive)
                    # and the sum is exactly S and product is divisible by S
                    if started and current_sum == S and current_prod_mod_S == 0:
                        return 1
                    return 0

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    new_started = started or (d != 0)

                    if not new_started:
                        # Still leading zeros, sum and product remain 0 and 1 (but effectively not started)
                        # We pass current_sum=0, current_prod_mod_S=1 (identity) but it doesn't matter as long as started is False
                        total += dp(pos + 1, 0, 1, new_tight, False)
                    else:
                        new_sum = current_sum + d
                        # If new_sum already exceeds S, skip
                        if new_sum > S:
                            continue
                        # Update product mod S: if it's the first digit, product is d, else current_prod * d
                        if not started:
                            # First non-zero digit
                            new_prod_mod = d % S
                        else:
                            new_prod_mod = (current_prod_mod_S * d) % S

                        total += dp(pos + 1, new_sum, new_prod_mod, new_tight, True)

                return total

            return dp(0, 0, 1, True, False)

        total = 0
        for S in range(1, 82):  # Sum of digits can be at most 9*9=81 for numbers < 10^9
            total += count_upto(r, S) - count_upto(l - 1, S)

        return total

