    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        # If removing any word leaves fewer than k words, answer is 0
        if n <= k:
            return [0] * n

        # Precompute prefix counts
        prefix_count = {}
        # Also store which prefixes each word has for quick lookup
        word_prefixes = []

        for word in words:
            prefixes = set()
            # Generate all prefixes for the word
            # To avoid storing too many, we can store them in a set for this word
            # But we need to add to global prefix_count
            # Since sum of lengths <= 10^5, we can iterate
            for j in range(1, len(word) + 1):
                p = word[:j]
                prefixes.add(p)
                prefix_count[p] = prefix_count.get(p, 0) + 1
            word_prefixes.append(prefixes)

        # Create list of all unique prefixes with their counts
        # We only care about prefixes that have count >= k or count >= k+1
        # Store as (length, count, prefix)
        all_prefixes = []
        for p, cnt in prefix_count.items():
            all_prefixes.append((len(p), cnt, p))

        # Sort by length descending
        all_prefixes.sort(key=lambda x: x[0], reverse=True)

        # Get top 2 prefixes for count >= k
        top_k = []
        for length, cnt, p in all_prefixes:
            if cnt >= k:
                top_k.append((length, cnt, p))
                if len(top_k) == 2:
                    break

        # Get top 2 prefixes for count >= k+1
        top_k1 = []
        for length, cnt, p in all_prefixes:
            if cnt >= k + 1:
                top_k1.append((length, cnt, p))
                if len(top_k1) == 2:
                    break

        # Precompute sets for top_k and top_k1 for quick lookup
        top_k_set = set(p for _, _, p in top_k)
        top_k1_set = set(p for _, _, p in top_k1)

        # For each word, compute the answer
        ans = []
        for i in range(n):
            # If the word itself is not in the top lists, we need to check
            # A = max length among prefixes of words[i] that are in top_k1
            A = 0
            for p in word_prefixes[i]:
                if p in top_k1_set:
                    # We need the length, so we should store it
                    # Actually, we can get it from the prefix itself
                    if len(p) > A:
                        A = len(p)

            # B = max length among top_k prefixes that are NOT in word_prefixes[i]
            B = 0
            for length, cnt, p in top_k:
                if p not in word_prefixes[i]:
                    if length > B:
                        B = length

            ans.append(max(A, B))

        return ans

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_len = n + m - 1

        # Initialize word array with None
        word = [None] * total_len
        # Track which positions are forced by T constraints
        forced = [False] * total_len

        # Process T constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if word[pos] is not None:
                        if word[pos] != str2[j]:
                            return ""
                    else:
                        word[pos] = str2[j]
                        forced[pos] = True

        # Fill non-forced positions with 'a'
        for i in range(total_len):
            if word[i] is None:
                word[i] = 'a'

        # Process F constraints
        # We iterate from left to right. For each F constraint that is violated,
        # we fix it by changing the rightmost non-forced character in its window.
        for i in range(n):
            if str1[i] == 'F':
                # Check if word[i:i+m] == str2
                # To avoid creating a new string slice every time (which is O(m)),
                # we can compare character by character.
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    # Violation found, need to fix
                    # Find the rightmost non-forced index j in [0, m-1]
                    fix_j = -1
                    for j in range(m - 1, -1, -1):
                        if not forced[i + j]:
                            fix_j = j
                            break

                    if fix_j == -1:
                        # No non-forced character to change, cannot fix
                        return ""

                    # Change word[i+fix_j] to break the match
                    # Set to 'a' if it's not equal to str2[fix_j], else 'b'
                    pos = i + fix_j
                    if word[pos] != str2[fix_j]:
                        # It's already not equal, but we are in a match situation,
                        # so this shouldn't happen. Actually, if it's not forced,
                        # it was set to 'a'. So if str2[fix_j] is not 'a', then
                        # word[pos] ('a') != str2[fix_j], so the substring wouldn't match.
                        # Therefore, if we are here, word[pos] must equal str2[fix_j].
                        # So we must change it to something else.
                        # The smallest character different from str2[fix_j] is:
                        # 'a' if str2[fix_j] != 'a', else 'b'
                        word[pos] = 'a' if str2[fix_j] != 'a' else 'b'
                    else:
                        # word[pos] == str2[fix_j], so we need to change it.
                        word[pos] = 'a' if str2[fix_j] != 'a' else 'b'

        # Final verification of all F constraints
        for i in range(n):
            if str1[i] == 'F':
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    return ""

        return "".join(word)

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        for d in range(1, 10):
            d_str = str(d)
            for j in range(n):
                if s[j] == d_str:
                    val = 0
                    power = 1
                    # Look back up to 9 characters
                    # The period of 10^k mod d is at most 9 for d in 1..9
                    # So looking back 9 characters is sufficient to capture one full period
                    for i in range(j, max(j - 9, -1), -1):
                        digit = int(s[i])
                        val = (digit * power + val) % d
                        power = (power * 10) % d
                        if val == 0:
                            ans += 1
        return ans

