    if not data:
        return

    iterator = iter(data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N_str = next(iterator)
            N = int(N_str)
        except StopIteration:
            break

        if N == 1:
            results.append("2 1")
            continue

        if N <= 59:
            M = (1 << N) - 1
            results.append(f"2 {M}")
            continue

        # For N > 59, we use the prime modulus construction
        # Find smallest prime p = k*N + 1
        k = 1
        while True:
            p = k * N + 1
            if is_prime_mr(p):
                break
            k += 1

        # p is a prime such that N divides p-1
        # We need an element of order N modulo p
        # Let g be a primitive root mod p.
        # Then A = g^((p-1)/N) mod p has order N.

        g = find_primitive_root(p)
        exponent = (p - 1) // N
        A = pow(g, exponent, p)

        results.append(f"{A} {p}")

    print('\n'.join(results))

